    "question": "How can nursing experience help make clinical systems easier to use safely?",
    "is_question": true,
    "form": "ISBAR handover: Identify, Situation, Background, Assessment, Recommendation.",
    "object": "One stylised blank ISBAR handover sheet represented as five connected paper panels.",
    "object_in_pieces": true
  },
  "tests": {
    "swap": {
      "result": "pass",
      "reason": "The concept rests on her handover redesign leadership, forty observation hours, three workarounds and scanner relocation."
    },
    "backdrop": {
      "result": "pass",
      "reason": "The panels organise observations, distinguish personal contributions from team outcomes and display the form comparison, giving them an explanatory role."
    },
    "depth": {
      "result": "pass",
      "reason": "The sequence establishes identity and intent, develops evidence and contributions, then completes a professional handover into the desired role."
    },
    "clipart": {
      "result": "pass",
      "reason": "The central object is a working document she helped redesign rather than a generic nursing emblem."
    },
    "honesty": {
      "result": "pass",
      "reason": "The plan uses official titles, credits the ward team, excludes prohibited assets and avoids unsupported outcomes."
    },
    "thirty_seconds": {
      "result": "pass",
      "reason": "The opening provides her name, current roles, clinical-informatics focus, five-person redesign leadership and a direct contact route."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "Plain-language chapter explanations and concrete work evidence make the clinical structure understandable without undermining its professional meaning."
    }
  },
